'use client';

import React from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { useAuth } from '@/hooks/useAuth';
import { api } from '@/lib/api';
import { Card } from '@/components/ui/Card';
import { AlertChannelForm } from '@/components/AlertChannelForm';
import { Mail, Webhook, Trash2, User, Bell } from 'lucide-react';
import type { AlertChannel, CreateAlertChannelInput } from '@pingwatch/shared';

export default function SettingsPage() {
  const { user } = useAuth();
  const queryClient = useQueryClient();

  const { data: channels = [], isLoading } = useQuery<AlertChannel[]>({
    queryKey: ['global-channels'],
    queryFn: () => api.getAlertChannels(),
  });

  const addChannelMutation = useMutation({
    mutationFn: (data: CreateAlertChannelInput) => api.createAlertChannel(data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['global-channels'] });
    },
  });

  const deleteChannelMutation = useMutation({
    mutationFn: (id: string) => api.deleteAlertChannel(id),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['global-channels'] });
    },
  });

  // Filter global channels (where site_id is null)
  const globalChannels = channels.filter((c) => !c.site_id);

  return (
    <div className="space-y-8 max-w-4xl animate-in fade-in duration-300">
      <div>
        <h1 className="text-2xl font-bold tracking-tight text-white">Settings</h1>
        <p className="text-xs text-[#8B949E] mt-1">
          Manage your account profile and global notification dispatch destinations.
        </p>
      </div>

      {/* Profile Section */}
      <Card className="p-6">
        <h2 className="text-sm font-semibold uppercase tracking-wider text-[#8B949E] flex items-center gap-2 mb-4">
          <User className="h-4 w-4 text-[#00FF87]" /> Account Information
        </h2>
        <div className="space-y-3">
          <div>
            <span className="text-xs text-[#8B949E] block">Authenticated Email</span>
            <span className="text-sm font-mono text-white block mt-0.5">
              {user?.email || 'dev@pingwatch.test'}
            </span>
          </div>
          <div>
            <span className="text-xs text-[#8B949E] block">User ID</span>
            <span className="text-xs font-mono text-[#6E7681] block mt-0.5">
              {user?.id || 'usr_demo_123'}
            </span>
          </div>
        </div>
      </Card>

      {/* Global Alert Channels */}
      <div className="space-y-4">
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
          <div>
            <h2 className="text-lg font-semibold text-white flex items-center gap-2">
              <Bell className="h-4 w-4 text-[#00FF87]" /> Global Alert Channels
            </h2>
            <p className="text-xs text-[#8B949E] mt-0.5">
              These channels receive downtime and recovery alerts for ALL monitored sites.
            </p>
          </div>
          <AlertChannelForm
            siteId={null}
            onAddChannel={(data) => addChannelMutation.mutateAsync(data)}
          />
        </div>

        {isLoading ? (
          <div className="h-24 bg-[#161B22] rounded-lg border border-[#30363D] animate-pulse" />
        ) : globalChannels.length === 0 ? (
          <div className="p-8 rounded-lg border border-dashed border-[#30363D] bg-[#161B22]/30 text-center">
            <Mail className="h-6 w-6 text-[#8B949E] mx-auto mb-2" />
            <p className="text-sm text-white font-medium">No global alert channels configured</p>
            <p className="text-xs text-[#8B949E] mt-1">
              Add your email address or an incident webhook to receive alerts when any monitored service goes down.
            </p>
          </div>
        ) : (
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
            {globalChannels.map((channel) => (
              <div
                key={channel.id}
                className="p-4 rounded-lg border border-[#30363D] bg-[#161B22] flex items-center justify-between"
              >
                <div className="flex items-center gap-3 min-w-0">
                  <div className="p-2 rounded bg-[#0D1117] border border-[#30363D]">
                    {channel.channel_type === 'email' ? (
                      <Mail className="h-4 w-4 text-[#00FF87]" />
                    ) : (
                      <Webhook className="h-4 w-4 text-[#58A6FF]" />
                    )}
                  </div>
                  <div className="min-w-0">
                    <span className="text-xs font-mono text-white block truncate">
                      {channel.config?.email || channel.config?.url}
                    </span>
                    <span className="text-[10px] text-[#8B949E] uppercase font-mono">
                      Global {channel.channel_type} alert
                    </span>
                  </div>
                </div>

                <button
                  type="button"
                  onClick={() => deleteChannelMutation.mutate(channel.id)}
                  className="p-1.5 text-[#8B949E] hover:text-[#FF4D4F] hover:bg-[#FF4D4F]/10 rounded transition-colors ml-2 flex-shrink-0"
                  title="Delete Channel"
                >
                  <Trash2 className="h-4 w-4" />
                </button>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}
